// === Tab: mySketch ===
/**
For the #WCCChallenge themed - 'Liminal Spaces'.

Inspired By severance series, this sketch represents an elevator and shaft as liminal space
and the transition or passage between two identities — the 'innie' and 'outie' from the series. 

Still working on improving the sketch 
Todo - Improve elevator and figure, not pausing elevator to sync with the music

By Neha Naik submitted on 06/07/2025	
**/


let bgMusic;
let elevatorSystem;
let particles = [];
let glitch;

function preload() {
  soundFormats('mp3', 'wav'); // just in case
  bgMusic = loadSound('https://openprocessing.org/sketch/2670816/files/severance-elevator-outie-innie.mp3'); // match uploaded filename
}

function setup(){
  createCanvas(800, 800);
	bgMusic.setLoop(true);
  userStartAudio(); // ensure browser unlocks audio
  bgMusic.play();
  elevatorSystem = new ElevatorSystem();
  for(let i = 0;i<250;i++){
    particles[i] = new Particle();
  }
  glitch = new Glitch();
}

function draw(){
  background(10);
  elevatorSystem.update();
  elevatorSystem.display();
  for(let i = 0;i<250;i++){
    particles[i].update();
    particles[i].display();

  }
  glitch.display(elevatorSystem.elevator.y);
}


// === Tab: particle.js ===
class Particle {

    constructor(){
        this.x = random(width);
        this.y = random(height);
        this.velocityX = random(-1,1);
        this.velocityY = random(-1, 1);
    }

    update(){
        this.x += this.velocityX;
        this.y += this.velocityY;
        if(this.x < 0 || this.x > width){
            this.velocityX *= -1;
        }
        if(this.y < 0 || this.y > height){
            this.velocityY *= -1;
        }
    }

    display(){
        stroke(255, 50);
        point(this.x, this.y);
    }

}

// === Tab: elevator.js ===
class Elevator{

    constructor(x, y){
        this.x = x;
        this.y = y;
        this.flickerAlpha = 0;
    }

    display(dir){
        const y = this.y;
        const x = this.x;

        //Elevator Frame
        fill(120);
        rectMode(CENTER);
        //70 105
        rect(x, y, 140, 210);

        //shadow below the elevator
        noStroke();
        fill(255, 25);
        //80 10
        ellipse(x, y+110, 160, 20);

        //Interior to add some depth
        push();
        fill(80);
        //40 80
        rect(x, y, 80, 160);
        fill(200);
        //40 20
        rect(x, y+60, 80, 40);
        fill(40);
        rect(x-35, y, 10, 160);
        rect(x+35, y, 10, 160);

        //vertical bars - add some flicker 
        // x = -30, -15, 15, 30, y = 160
        for(let vx = x-30;vx<=x+30;vx+=15){
            let flicker = random(30, 80);
            stroke(150, 255, 255, flicker);
            line(vx, y-80, vx, y+80);
        }

        //interior flicker
        noStroke();
        this.flickerAlpha = random(10, 30);
        fill(255, this.flickerAlpha);
        rect(x, y, 80, 160);

        // Figure
				fill(20);
				ellipse(x, y + 30, 20, 40); // body
				ellipse(x, y + 10, 15, 15); // head

				// Scan flicker
				let scanY = y + map(sin(frameCount * 0.05), -1, 1, -80, 80);
				stroke(100, 200, 255, 40);
				line(x - 40, scanY, x + 40, scanY);

        //arrow indicator
        fill(120);
        rect(x, y-130, 60, 30);
        fill(255, 60, 60);
        // 1 = down, -1 = up
        if(dir === -1){
            triangle(x, y - 138, x - 10, y - 122, x + 10, y - 122);
        }else{
            triangle(x, y - 122, x - 10, y - 138, x + 10, y - 138);
        }
    }
}

// === Tab: elevatorSystem.js ===
class ElevatorSystem{

    constructor(){
        this.elevator = new Elevator(width/2, height-120);
        this.shaft = new ShaftBody();
        this.floorHeight = 240; //elevator h is 210 
        this.dir = -1;
			  this.pauseElevator = 0;

    }

    update(){
        const elevatorCenter = 210/2; // height 210
        const indicatorHeight = 30;
        const topLimit = elevatorCenter+ indicatorHeight;
        const bottomLimit = height - elevatorCenter - indicatorHeight;

			  if (this.pauseElevator > 0) {
      		this.pauseElevator--; // countdown
      		return;             // pause in place
    		}

        // up down 2 pixels per frame 
        this.elevator.y += this.dir * 2;

        //check for top bottom floors
        if(this.elevator.y <= topLimit || this.elevator.y >= bottomLimit){
            this.dir *= -1;
            this.elevator.y = constrain(this.elevator.y, topLimit, bottomLimit);
						this.pauseElevator = 0; // no pause syncs with the music, increase later
        }
    }

    display(){
        this.shaft.display(this.floorHeight);
        this.elevator.display(this.dir);
    }
}

// === Tab: shaftBody.js ===
class ShaftBody {

    display(floorHeight) {

        const totalFloors = Math.ceil(height / floorHeight) + 1;

			  //vertical shaft lines
        stroke(60);
        strokeWeight(2);
        //elevator width is 140 
        for (let x = width / 2 - 70; x <= width / 2 + 70; x += 20) {
            line(x, 0, x, height);
        }

        // calculated from bottom up 0 - ~3
        for (let i = 0; i < totalFloors; i++) {
            var y = height - i * floorHeight;
            line(0, y, width, y);
						      // Soft glow at floor

            //beams for each floor offset x and y both for beams
            let alpha = map(sin(frameCount * 0.05 + i), -1, 1, 50, 100);
            for (let offset = 0; offset < 100; offset += 2) {
                stroke(100, 200, 255, alpha - offset);
                //stroke(255, 255, 10, lightAlpha - offset);
                line(offset, y, width / 2, y + offset)
                line(width - offset, y, width / 2, y + offset);
            }

            let labelY = y - 15;
            noStroke();
            fill(200);
            textSize(12);
            text("FLOOR " + i, 30, labelY);
            stroke(255, 30);
        }


        // Distant vertical light shafts
        for (let i = -2; i <= 2; i++) {
            let offsetX = i * 150;
            if (abs(offsetX) > 80) { // Skip central shaft area
                for (let j = 0; j < height; j += 100) {
                    var flicker = random(50, 100);
                    stroke(100, 130, 255, flicker);
                    line(width / 2 + offsetX, j, width / 2 + offsetX, j + 50);
                }
            }
        }
        // 10 verticle flickering bars
        for (let i = 0; i < height; i += 80) {
            var flicker = random(20, 80);
            stroke(100, 200, 255, flicker);
            line(width / 2 - 70, i, width / 2 + 70, i);
        }

        // Draw LEVEL INNIE and OUTIE labels
        noStroke();
        textAlign(CENTER, CENTER);
        textSize(18);
        fill(255, 100, 100);
        text("LEVEL OUTIE", width / 2, 40);
        text("LEVEL INNIE", width / 2, height - 40);

    }

}

// === Tab: glitch.js ===
class Glitch{

    display(elevatorPos){
        for(let i = 0;i<5;i++){
            stroke(255, random(20, 60));
            var y = elevatorPos + random(-50, 50);
            line(random(width), y, random(width), y);
        }
    }
}

